{
  "title": "Discussion on Tax Filing, Domain Purchase, and App Idea Viability",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Tax filing complications and workaround",
      "claims": [
        {
          "text": "The user paid 500 UAH to aunt Sveta to correct a large amount of main tax liability caused by a column mislabel in the declaration.",
          "evidence": [1]
        },
        {
          "text": "The inspector ignored the user's declarations for 1.5 years, then was reprimanded and started demanding the user re‑verify all past declarations.",
          "evidence": [1]
        },
        {
          "text": "With Sveta's help the user managed to correctly re‑file and paid about 1000 UAH instead of all fines.",
          "evidence": [1]
        },
        {
          "text": "The whole procedure takes about an hour with Excel, up to one day maximum.",
          "evidence": [5,6]
        },
        {
          "text": "The critical issue is not the tax calculation itself but correctly matching each column and subtraction.",
          "evidence": [8]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Domain purchase discussion",
      "claims": [
        {
          "text": "User has not bought a domain yet.",
          "evidence": [2]
        },
        {
          "text": "Someone needs to buy a calculator first, then there will be money for a domain.",
          "evidence": [4]
        },
        {
          "text": "One participant doubts anyone will buy the domain.",
          "evidence": [9]
        },
        {
          "text": "Another participant describes the domain as a “sick thing” that won’t evaporate even in heat.",
          "evidence": [10]
        }
      ]
    },
    {
      "id": "app-viability",
      "title": "Viability of a quick‑delivery cross‑platform app",
      "claims": [
        {
          "text": "Web platform is the simplest but far less profitable than Android/iOS.",
          "evidence": [11]
        },
        {
          "text": "Web SEO is poor; even on the 10th Google page the site is not found.",
          "evidence": [11]
        },
        {
          "text": "No external traffic from Instagram/Threads, no contextual ads; app stores promote new apps more effectively.",
          "evidence": [11]
        },
        {
          "text": "No passive ad revenue on a website; user retention is near zero because of immediate paywall.",
          "evidence": [11]
        },
        {
          "text": "Conversion is presumed zero; product does not simplify much nor integrate with banks or tax cabinets.",
          "evidence": [11]
        },
        {
          "text": "Successful approach described: rapid delivery (< 1 week), cross‑platform stack (Flutter), copying popular ideas with minor tweaks.",
          "evidence": [12]
        },
        {
          "text": "The idea discussed is about Ihar trying to make money.",
          "evidence": [13,14]
        },
        {
          "text": "Skepticism that anyone will buy the product; wager that nobody will purchase within months.",
          "evidence": [17]
        },
        {
          "text": "LinkedIn audience for technical/managerial/sales posts has dropped below 50%.",
          "evidence": [18]
        },
        {
          "text": "The calculator only works with UAH‑based FOP; foreign‑currency FOP requires daily exchange‑rate calculations.",
          "evidence": [19]
        },
        {
          "text": "Before building, need to verify at least ten people are willing to pay 299 UAH.",
          "evidence": [20]
        },
        {
          "text": "Password for the app is stored plainly in local storage as a 100 % discount promo code.",
          "evidence": [20]
        },
        {
          "text": "User asks if the source code can be found by searching for the password.",
          "evidence": [21]
        },
        {
          "text": "Another participant mocks the idea of paying 299 UAH for it.",
          "evidence": [22]
        },
        {
          "text": "The app is positioned as a local‑first app with USD/UAH rate fetched every 5 minutes; calculations happen instantly in the browser.",
          "evidence": [29]
        },
        {
          "text": "A participant describes the project as a “free vibe‑code” made out of boredom, suggesting only insiders will look for the password.",
          "evidence": [30,31]
        },
        {
          "text": "Someone calls the creator a scammer.",
          "evidence": [32]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Is the source code searchable to find the password?",
      "evidence": [21]
    }
  ]
}
